using System.Collections.Generic;
using NUnit.Framework;
using UnityEngine;

namespace Claybreak.Tests
{
    /// <summary>
    /// RT-6: levels generated by data (deterministic, valid against the pool, a ramp that never gets easier,
    /// the boss on top), the replay adjustment of D19 (top upgrades do not make an old world trivial; a first
    /// pass is never adjusted) and the save migration to version 3 (world 1 grew from 7 to 10 levels).
    /// </summary>
    public sealed class ContentGenerationTests
    {
        private static WorldRecipe Recipe(int seed = 7, BossRule rule = BossRule.ShieldReturns) => new WorldRecipe
        {
            worldId = "test",
            seed = seed,
            levelCount = 10,
            bossRule = rule,
            expectedDamage = 1.3f,
            startFirst = 14,
            startLast = 20,
            shieldFrom = 2,
            rewardFirst = 100,
            rewardLast = 160,
            bossReward = 350
        };

        private static List<ClaybreakLevel> made = new List<ClaybreakLevel>();

        [TearDown]
        public void TearDown()
        {
            foreach (ClaybreakLevel level in made)
            {
                Object.DestroyImmediate(level);
            }

            made.Clear();
        }

        private static ClaybreakLevel Asset(LevelSpec spec)
        {
            var level = ScriptableObject.CreateInstance<ClaybreakLevel>();
            level.EditorAssign(spec);
            made.Add(level);
            return level;
        }

        [Test]
        public void TheSameRecipeMakesTheSameLevels()
        {
            LevelSpec[] a = LevelGenerator.GenerateWorld(Recipe());
            LevelSpec[] b = LevelGenerator.GenerateWorld(Recipe());
            for (int i = 0; i < a.Length; i++)
            {
                Assert.AreEqual(JsonUtility.ToJson(a[i]), JsonUtility.ToJson(b[i]), "level " + (i + 1));
            }

            Assert.AreNotEqual(JsonUtility.ToJson(a[4]), JsonUtility.ToJson(LevelGenerator.GenerateWorld(Recipe(8))[4]),
                "another seed makes another layout");
        }

        [Test]
        public void EveryGeneratedLevelIsValidAndOnlyTheLastIsTheBoss([Values(1, 2, 3, 42, 99)] int seed,
            [Values(BossRule.ShiftGates, BossRule.ShieldReturns, BossRule.Overheat, BossRule.TurnGate)] BossRule rule)
        {
            LevelSpec[] specs = LevelGenerator.GenerateWorld(Recipe(seed, rule));
            for (int i = 0; i < specs.Length; i++)
            {
                ClaybreakLevel level = Asset(specs[i]);
                Assert.IsTrue(level.TryValidate(300, 300, out string error), $"seed {seed} level {i + 1}: {error}");
                Assert.AreEqual(i == specs.Length - 1, level.IsBoss, "level " + (i + 1));
                Assert.LessOrEqual(specs[i].runGates.Length, RunGateCourse.MaximumPairs);
                Assert.GreaterOrEqual(specs[i].runGates.Length, 3);
            }

            Assert.AreEqual(rule, specs[specs.Length - 1].bossRule);
            Assert.AreEqual(ClaybreakLevel.MaximumFloors, specs[specs.Length - 1].floors);
        }

        [Test]
        public void HealthRampsUpAndTheBossIsTheToughest([Values(1, 5, 13, 77)] int seed)
        {
            LevelSpec[] specs = LevelGenerator.GenerateWorld(Recipe(seed));
            int boss = specs[specs.Length - 1].towerHealth;
            for (int i = 1; i < specs.Length; i++)
            {
                Assert.Greater(specs[i].towerHealth, specs[i - 1].towerHealth, $"level {i + 1} is not tougher than level {i}");
                Assert.GreaterOrEqual(specs[i].coinReward, specs[i - 1].coinReward, "rewards never drop");
            }

            for (int i = 0; i < specs.Length - 1; i++)
            {
                Assert.Less(specs[i].towerHealth, boss);
            }
        }

        [Test]
        public void TowerHealthFollowsThePotentialHitsAndTheExpectedDamage()
        {
            WorldRecipe recipe = Recipe();
            LevelSpec level = LevelGenerator.Generate(recipe, 4);
            float share = (float)level.towerHealth / (LevelGenerator.PotentialHits(level) * recipe.expectedDamage);
            Assert.That(share, Is.InRange(0.4f, 0.75f));
            Assert.LessOrEqual(LevelGenerator.BestArmy(level), LevelGenerator.ArmyCap);
        }

        [Test]
        public void HandMadeLevelsStayAndGeneratedOnesRampBetweenThem()
        {
            var fixedLevels = new LevelSpec[10];
            fixedLevels[0] = LevelGenerator.Generate(Recipe(), 0);
            fixedLevels[0].towerHealth = 123;
            fixedLevels[9] = LevelGenerator.Generate(Recipe(), 9);
            fixedLevels[9].towerHealth = 600;
            LevelSpec[] specs = LevelGenerator.GenerateWorld(Recipe(), fixedLevels);
            Assert.AreSame(fixedLevels[0], specs[0]);
            Assert.AreEqual(123, specs[0].towerHealth);
            Assert.AreEqual(600, specs[9].towerHealth);
            for (int i = 1; i < 9; i++)
            {
                Assert.Less(specs[i].towerHealth, 600);
                Assert.Greater(specs[i].towerHealth, specs[i - 1].towerHealth);
            }
        }

        [Test]
        public void DefensesComeInByTheProfile()
        {
            LevelSpec[] specs = LevelGenerator.GenerateWorld(Recipe());
            Assert.IsFalse(specs[0].shieldEnabled || specs[1].shieldEnabled, "the shield comes in at level 3");
            Assert.IsFalse(specs[0].wallEnabled, "no wall on the first level");
            Assert.IsTrue(specs[9].shieldEnabled && specs[9].wallEnabled && specs[9].sweeperEnabled, "the boss has every defense");
            bool anyShield = false;
            for (int i = 2; i < 9; i++)
            {
                anyShield |= specs[i].shieldEnabled;
            }

            Assert.IsTrue(anyShield, "the world teaches the shield before its boss");
        }

        [Test]
        public void ReplaysGrowWithThePlayerPowerButAFirstPassNeverDoes()
        {
            using var content = new TestContent();
            var save = new SaveData();
            save.worlds = new[] { new WorldSave { id = SaveMigration.V1WorldId, loop = 0 } };
            save.upgrades = new[] { new UpgradeSave { id = "damage", level = 5 }, new UpgradeSave { id = "launch", level = 5 } };
            var progression = new Progression(content.Catalog, save);
            Assert.AreEqual(1f, progression.PowerAdjustment, "first pass: upgrades always show");
            Assert.AreEqual(100, progression.ScaleHealth(100));

            progression.Save.worlds[0].loop = 2;
            float power = 1.8f * (1f + 0.5f * 0.6f);
            float expected = Mathf.Pow(power / TestContent.ExpectedDamage, 0.7f);
            Assert.AreEqual(expected, progression.PowerAdjustment, 1e-4f);
            Assert.AreEqual(Mathf.RoundToInt(100 * 1.5f * expected), progression.ScaleHealth(100));

            progression.Save.upgrades = new UpgradeSave[0];
            Assert.AreEqual(1f, progression.PowerAdjustment, "a weak player is never pushed below the loop rule");
            Assert.AreEqual(150, progression.ScaleHealth(100));
        }

        [Test]
        public void World1GrewToTenLevelsAndTheBossKeepsItsStars()
        {
            string v2 = "{\"version\":2,\"coins\":50,\"world\":\"world1\",\"worlds\":[{\"id\":\"world1\",\"nextLevel\":6,\"loop\":1,"
                + "\"stars\":[3,2,3,1,2,3,2]}],\"upgrades\":[],\"units\":[],\"loadout\":[],\"skins\":[],\"skin\":\"\",\"levelsWon\":9,\"levelsLost\":1}";
            Assert.IsTrue(SaveStore.TryDeserialize(v2, out SaveData save, out int version));
            Assert.AreEqual(2, version);
            Assert.AreEqual(SaveData.CurrentVersion, save.version);
            WorldSave world = save.worlds[0];
            CollectionAssert.AreEqual(new[] { 3, 2, 3, 1, 2, 3, 0, 0, 0, 2 }, world.stars);
            Assert.AreEqual(6, world.nextLevel, "a player at the old boss meets the first new level");
            Assert.AreEqual(1, world.loop);

            string v3 = SaveStore.Serialize(save);
            Assert.IsTrue(SaveStore.TryDeserialize(v3, out SaveData again, out int read));
            Assert.AreEqual(SaveData.CurrentVersion, read);
            CollectionAssert.AreEqual(world.stars, again.worlds[0].stars, "a version-3 save is not migrated again");
        }
    }
}
